export default [
  {"m": "Primeros pasos con C", "t": "Qué es C", "x": "Lenguaje de programación compilado, rápido y cercano al hardware.\n\nC nació en 1972 y es la base de muchos lenguajes modernos. Te da control directo de la memoria, a cambio de mayor responsabilidad.", "u": "Escribir sistemas operativos, controladores y programas muy eficientes.\n\nNecesitas programar un componente muy rápido que hable casi directo con el hardware.", "p": ["C es un lenguaje compilado.", "C permite controlar la memoria directamente.", "Muchos sistemas operativos están escritos en C."], "c": "#include <stdio.h>\n\nint main(void) {\n    printf(\"Hola desde C\\n\");   // un programa mínimo en C\n    return 0;\n}", "h": "Muestra un saludo desde un programa en C.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: C es un lenguaje ___ antes de ejecutarse. (compilado)", "e": "Creer que C se ejecuta línea a línea sin compilar."},
  {"m": "Primeros pasos con C", "t": "Compilar con gcc", "x": "Paso que traduce el código C a un programa ejecutable.\n\ngcc lee tus archivos .c y genera un ejecutable. Con gcc hola.c -o hola creas el programa hola. Si hay errores de sintaxis, no lo genera.", "u": "Convertir tu código fuente en algo que la máquina entiende.\n\nEscribiste un archivo hola.c y necesitas convertirlo en un programa que se pueda ejecutar.", "p": ["gcc compila código C a un ejecutable.", "La opción -o elige el nombre del ejecutable.", "Los errores de sintaxis impiden compilar."], "c": "#include <stdio.h>\n\nint main(void) {\n    printf(\"Compilado con gcc\\n\");   // gcc hola.c -o hola\n    return 0;\n}", "h": "Muestra un mensaje de un programa compilado con gcc.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El compilador más usado para C se llama ___. (3 letras)", "e": "Intentar ejecutar el archivo .c sin compilarlo antes."},
  {"m": "Primeros pasos con C", "t": "Función main", "x": "Función donde empieza la ejecución de todo programa C.\n\nTodo programa C tiene una función main. Devuelve un int: 0 significa que terminó bien y otro valor indica un error.", "u": "Indicar por dónde arranca el programa.\n\nTu programa compila pero el enlazador dice que no encuentra por dónde empezar.", "p": ["main es el punto de entrada del programa.", "main devuelve un int al terminar.", "Devolver 0 indica que todo salió bien."], "c": "#include <stdio.h>\n\nint main(void) {   // aquí empieza todo\n    printf(\"Dentro de main\\n\");\n    return 0;      // 0 = sin errores\n}", "h": "Ejecuta el código dentro de main y devuelve 0.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función donde empieza un programa C es ___. (4 letras)", "e": "Olvidar la función main. La función de entrada debe llamarse main."},
  {"m": "Primeros pasos con C", "t": "#include", "x": "Directiva que incorpora un archivo de cabecera al programa.\n\n#include <stdio.h> trae las declaraciones de printf y scanf. Las cabeceras estándar van entre ángulos y las propias entre comillas.", "u": "Usar funciones de las bibliotecas estándar.\n\nQuieres usar printf pero el compilador no la reconoce.", "p": ["#include incorpora una cabecera al programa.", "stdio.h declara printf y scanf.", "Las cabeceras propias se incluyen con comillas."], "c": "#include <stdio.h>    // funciones de entrada y salida\n#include <math.h>     // funciones matemáticas\n\nint main(void) {\n    printf(\"%.1f\\n\", sqrt(16.0));\n    return 0;\n}", "h": "Incluye dos cabeceras y calcula una raíz cuadrada.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La directiva para usar una biblioteca empieza con #___. (7 letras)", "e": "Usar printf sin incluir stdio.h."},
  {"m": "Primeros pasos con C", "t": "printf", "x": "Función que escribe texto formateado en la pantalla.\n\nprintf escribe el texto que recibe. El carácter especial \\n produce un salto de línea. Sin él, todo sale seguido.", "u": "Mostrar mensajes y valores al usuario.\n\nDebes mostrar un mensaje al usuario y pasar a la línea siguiente.", "p": ["printf escribe texto en la pantalla.", "\\n produce un salto de línea.", "printf viene de stdio.h."], "c": "#include <stdio.h>\n\nint main(void) {\n    printf(\"Línea 1\\n\");   // \\n salta de línea\n    printf(\"Línea 2\\n\");\n    return 0;\n}", "h": "Muestra dos líneas de texto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que escribe en pantalla es ___. (6 letras)", "e": "Olvidar \\n y que todo el texto salga en una sola línea."},
  {"m": "Primeros pasos con C", "t": "Formatos de printf", "x": "Marcadores como %d, %f, %c y %s que insertan valores en el texto.\n\n%d es para enteros, %f para decimales, %c para un carácter y %s para cadenas. Cada marcador se reemplaza por el valor que le sigue.", "u": "Mostrar variables dentro de un mensaje.\n\nQuieres mostrar «Ana tiene 20 años» usando variables dentro del mensaje.", "p": ["%d muestra un entero.", "%f muestra un decimal.", "%s muestra una cadena de texto."], "c": "#include <stdio.h>\n\nint main(void) {\n    int edad = 20;\n    printf(\"Ana tiene %d años\\n\", edad);   // %d recibe edad\n    printf(\"Altura: %.2f\\n\", 1.65);        // %.2f: dos decimales\n    return 0;\n}", "h": "Inserta una edad y una altura dentro de mensajes.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El marcador para un entero en printf es %___. (d)", "e": "Usar %d para mostrar un decimal. %s es para cadenas; un entero se muestra con %d."},
  {"m": "Primeros pasos con C", "t": "Comentarios", "x": "Texto que el compilador ignora.\n\n// comenta hasta el final de la línea y /* ... */ comenta varias líneas. Un buen comentario explica el porqué, no lo obvio.", "u": "Explicar el código a quien lo lea.\n\nQuieres dejar una nota para otro programador que no afecte al programa.", "p": ["Los comentarios son ignorados por el compilador.", "// comenta una línea.", "/* */ permite comentar varias líneas."], "c": "#include <stdio.h>\n\nint main(void) {\n    // comentario de una línea\n    /* comentario\n       de varias líneas */\n    printf(\"Los comentarios no se ejecutan\\n\");\n    return 0;\n}", "h": "Muestra un mensaje; los comentarios se ignoran.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El comentario de una línea empieza con ___. (//)", "e": "Olvidar cerrar un comentario /* */."},
  {"m": "Primeros pasos con C", "t": "Variables", "x": "Espacio con nombre que guarda un valor en memoria.\n\nEn C debes declarar el tipo de cada variable antes de usarla: tipo nombre = valor;. El tipo decide cuánta memoria ocupa y qué valores admite.", "u": "Almacenar datos que el programa va a usar.\n\nNecesitas guardar la edad de un usuario para usarla después.", "p": ["Una variable guarda un valor con nombre.", "En C hay que declarar el tipo de la variable.", "El tipo decide qué valores admite."], "c": "#include <stdio.h>\n\nint main(void) {\n    int edad = 20;      // tipo nombre = valor\n    edad = edad + 1;    // la variable puede cambiar\n    printf(\"%d\\n\", edad);\n    return 0;\n}", "h": "Guarda una edad y la aumenta en uno.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Antes de usar una variable en C hay que declarar su ___. (4 letras)", "e": "Usar una variable sin declararla antes. total no se declaró: falta indicar su tipo (int total)."},
  {"m": "Primeros pasos con C", "t": "int", "x": "Tipo para guardar números enteros.\n\nUn int suele ocupar 4 bytes. Guarda enteros positivos y negativos. La división entre dos int descarta los decimales.", "u": "Contar y calcular con valores sin decimales.\n\nDebes guardar la cantidad de alumnos de una clase.", "p": ["int guarda números enteros.", "La división entre int descarta los decimales.", "Un int suele ocupar 4 bytes."], "c": "#include <stdio.h>\n\nint main(void) {\n    int alumnos = 25;\n    printf(\"%d\\n\", alumnos / 2);   // 12: se pierden los decimales\n    return 0;\n}", "h": "Divide un entero entre 2 y pierde los decimales.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo para números enteros es ___. (3 letras)", "e": "Esperar decimales al dividir dos enteros."},
  {"m": "Primeros pasos con C", "t": "float y double", "x": "Tipos para guardar números con decimales.\n\nfloat tiene menos precisión y ocupa menos; double tiene más precisión y es el más usado. Los literales decimales como 3.14 son double por defecto.", "u": "Trabajar con medidas y cálculos no enteros.\n\nNecesitas guardar la altura de una persona con decimales y buena precisión.", "p": ["float y double guardan números decimales.", "double tiene más precisión que float.", "3.14 es un double por defecto."], "c": "#include <stdio.h>\n\nint main(void) {\n    double altura = 1.75;\n    float peso = 70.5f;\n    printf(\"%.2f %.1f\\n\", altura, peso);\n    return 0;\n}", "h": "Guarda una altura y un peso decimales.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo decimal de mayor precisión es ___. (6 letras)", "e": "Usar int para guardar valores con decimales."},
  {"m": "Primeros pasos con C", "t": "char", "x": "Tipo que guarda un solo carácter.\n\nUn char ocupa 1 byte y se escribe entre comillas simples, como 'A'. Internamente guarda un número: el código ASCII de la letra.", "u": "Trabajar con letras y símbolos sueltos.\n\nQuieres guardar la inicial de un nombre, solo una letra.", "p": ["char guarda un solo carácter.", "Un char se escribe entre comillas simples.", "Internamente un char es un número (código ASCII)."], "c": "#include <stdio.h>\n\nint main(void) {\n    char inicial = 'A';\n    printf(\"%c vale %d\\n\", inicial, inicial);   // letra y su código ASCII\n    return 0;\n}", "h": "Muestra una letra y su código ASCII.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un solo carácter se guarda en una variable de tipo ___. (4 letras)", "e": "Usar comillas dobles para un char."},
  {"m": "Primeros pasos con C", "t": "const", "x": "Palabra que impide cambiar el valor de una variable.\n\nUna variable const debe inicializarse al declararla. Si intentas cambiarla después, el compilador da error.", "u": "Proteger valores que no deben modificarse.\n\nEl valor de pi no debe cambiar jamás durante el programa.", "p": ["const impide modificar una variable.", "Una variable const se inicializa al declararla.", "Cambiarla produce un error de compilación."], "c": "#include <stdio.h>\n\nint main(void) {\n    const double PI = 3.14159;   // no se puede modificar\n    printf(\"%.2f\\n\", PI * 2);\n    return 0;\n}", "h": "Usa una constante PI para un cálculo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que crea una variable inmodificable es ___. (5 letras)", "e": "Intentar asignar un nuevo valor a una constante. n es const y no se puede reasignar."},
  {"m": "Primeros pasos con C", "t": "#define", "x": "Directiva que define una constante o macro simple.\n\nEl preprocesador sustituye el nombre por su valor antes de compilar. No lleva punto y coma ni signo igual. Por convención se escribe en mayúsculas.", "u": "Dar nombre a valores que se repiten.\n\nUn valor aparece en veinte lugares y quieres cambiarlo en uno solo.", "p": ["#define sustituye un nombre por un valor antes de compilar.", "#define no lleva punto y coma.", "Por convención se escribe en mayúsculas."], "c": "#include <stdio.h>\n#define MAX 10   // sin signo igual ni punto y coma\n\nint main(void) {\n    printf(\"%d\\n\", MAX * 2);\n    return 0;\n}", "h": "Usa una constante MAX definida con #define.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La directiva para definir una constante es #___. (6 letras)", "e": "Poner punto y coma al final de un #define."},
  {"m": "Primeros pasos con C", "t": "Operadores aritméticos", "x": "Símbolos + - * / que realizan cálculos.\n\nSuman, restan, multiplican y dividen. La multiplicación y la división se evalúan antes que la suma y la resta; los paréntesis cambian el orden.", "u": "Hacer operaciones matemáticas.\n\nDebes calcular el total de 3 productos a 5 euros más 2 de envío.", "p": ["+, -, * y / son operadores aritméticos.", "* y / se evalúan antes que + y -.", "Los paréntesis cambian el orden de evaluación."], "c": "#include <stdio.h>\n\nint main(void) {\n    int total = 3 * 5 + 2;   // primero 3*5, luego +2\n    printf(\"%d\\n\", total);\n    printf(\"%d\\n\", 3 * (5 + 2));\n    return 0;\n}", "h": "Calcula un total con multiplicación y suma.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador que multiplica es ___. (un signo)", "e": "Olvidar que * se evalúa antes que +."},
  {"m": "Primeros pasos con C", "t": "Resto %", "x": "Operador que devuelve el resto de una división entera.\n\n7 % 3 vale 1 porque 7 = 2*3 + 1. Un número es par cuando n % 2 vale 0. Solo funciona con enteros.", "u": "Saber si un número es par o múltiplo de otro.\n\nNecesitas saber si un número es par.", "p": ["% devuelve el resto de una división.", "n % 2 == 0 indica que n es par.", "% solo funciona con enteros."], "c": "#include <stdio.h>\n\nint main(void) {\n    printf(\"%d\\n\", 7 % 3);          // resto 1\n    printf(\"%d\\n\", 10 % 2 == 0);    // 1: es par\n    return 0;\n}", "h": "Calcula un resto y comprueba si 10 es par.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador que da el resto de una división es el signo ___. (%)", "e": "Usar % con números decimales."},
  {"m": "Primeros pasos con C", "t": "Incremento ++ y --", "x": "Operadores que suman o restan uno a una variable.\n\ni++ equivale a i = i + 1 e i-- a i = i - 1. Se usan mucho en bucles. Como prefijo (++i) o sufijo (i++) cambian cuándo se aplica el cambio.", "u": "Contar de uno en uno de forma corta.\n\nQuieres sumar uno a un contador cada vez que ocurre algo, escribiendo lo menos posible.", "p": ["++ suma uno a una variable.", "-- resta uno a una variable.", "i++ equivale a i = i + 1."], "c": "#include <stdio.h>\n\nint main(void) {\n    int i = 5;\n    i++;               // ahora 6\n    i--;               // vuelve a 5\n    printf(\"%d\\n\", i);\n    return 0;\n}", "h": "Suma y resta uno a una variable.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador que suma uno a una variable es ___. (++)", "e": "Confundir i++ con ++i dentro de una expresión."},
  {"m": "Primeros pasos con C", "t": "Operadores de comparación", "x": "Símbolos como ==, !=, <, > que comparan dos valores.\n\nDevuelven 1 (verdadero) o 0 (falso). Para igualdad se usa == (dos signos); un solo = asigna y no compara.", "u": "Construir condiciones.\n\nQuieres saber si la edad es mayor o igual a 18.", "p": ["Los operadores de comparación devuelven 1 o 0.", "== compara igualdad.", "Un solo = asigna un valor, no compara."], "c": "#include <stdio.h>\n\nint main(void) {\n    int edad = 20;\n    printf(\"%d\\n\", edad >= 18);   // 1: verdadero\n    printf(\"%d\\n\", edad == 30);   // 0: falso\n    return 0;\n}", "h": "Compara una edad con dos valores.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para comprobar igualdad se usa el operador ___. (==)", "e": "Usar = en lugar de == dentro de un if."},
  {"m": "Primeros pasos con C", "t": "Operadores lógicos", "x": "Operadores &&, || y ! que combinan condiciones.\n\n&& es «y» (ambas verdaderas), || es «o» (basta una) y ! invierte. Evalúan de izquierda a derecha y se detienen en cuanto conocen el resultado.", "u": "Comprobar varias condiciones a la vez.\n\nQuieres comprobar que la edad sea mayor de 17 y además menor de 65.", "p": ["&& exige que se cumplan ambas condiciones.", "|| acepta que se cumpla alguna.", "! invierte una condición."], "c": "#include <stdio.h>\n\nint main(void) {\n    int edad = 30;\n    printf(\"%d\\n\", edad > 17 && edad < 65);   // 1\n    printf(\"%d\\n\", edad < 10 || edad > 20);   // 1\n    printf(\"%d\\n\", !(edad > 20));             // 0\n    return 0;\n}", "h": "Combina condiciones con y, o, no.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador lógico «y» se escribe ___. (&&)", "e": "Usar & en lugar de && para combinar condiciones."},
  {"m": "Primeros pasos con C", "t": "if y else", "x": "Estructura que ejecuta código según una condición.\n\nif ejecuta su bloque si la condición es distinta de cero. else cubre el caso contrario y else if permite encadenar varias condiciones.", "u": "Tomar decisiones en el programa.\n\nDebes mostrar un mensaje distinto según el usuario sea mayor de edad o no.", "p": ["if ejecuta un bloque solo si la condición es verdadera.", "else se ejecuta cuando la condición es falsa.", "else if encadena condiciones."], "c": "#include <stdio.h>\n\nint main(void) {\n    int edad = 20;\n    if (edad >= 18) {\n        printf(\"Mayor de edad\\n\");\n    } else {\n        printf(\"Menor de edad\\n\");\n    }\n    return 0;\n}", "h": "Muestra si una persona es mayor de edad.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra del caso contrario de un if es ___. (4 letras)", "e": "Usar = dentro de la condición del if. x = 3 asigna; para comparar hay que usar x == 3."},
  {"m": "Primeros pasos con C", "t": "switch", "x": "Estructura que elige entre varios casos según un valor.\n\nswitch compara una expresión entera con cada case. Cada caso suele terminar con break; si lo olvidas, la ejecución continúa en el siguiente (fall-through). default cubre los casos no previstos.", "u": "Reemplazar muchos if encadenados.\n\nSegún el número de día (1 a 7) debes mostrar su nombre y tienes muchas opciones.", "p": ["switch elige un caso según un valor.", "break evita seguir con el caso siguiente.", "default cubre los valores no previstos."], "c": "#include <stdio.h>\n\nint main(void) {\n    int dia = 2;\n    switch (dia) {\n        case 1: printf(\"Lunes\\n\"); break;\n        case 2: printf(\"Martes\\n\"); break;   // break evita el fall-through\n        default: printf(\"Otro día\\n\");\n    }\n    return 0;\n}", "h": "Muestra el nombre del día según su número.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que evita pasar al siguiente caso es ___. (5 letras)", "e": "Olvidar break y ejecutar varios casos seguidos."},
  {"m": "Bucles, funciones y arrays", "t": "Bucle while", "x": "Bucle que repite un bloque mientras una condición sea verdadera.\n\nwhile evalúa la condición antes de cada vuelta. Si la condición es falsa desde el inicio, el bloque no se ejecuta nunca. Cuida que algo dentro cambie la condición.", "u": "Repetir cuando no sabes cuántas veces.\n\nDebes seguir pidiendo algo hasta que ocurra un evento, sin saber cuántas veces.", "p": ["while repite mientras la condición sea verdadera.", "La condición se evalúa antes de cada vuelta.", "Si la condición nunca cambia, el bucle no termina."], "c": "#include <stdio.h>\n\nint main(void) {\n    int n = 3;\n    while (n > 0) {          // mientras n sea mayor que 0\n        printf(\"n = %d\\n\", n);\n        n--;                 // cambia la condición\n    }\n    return 0;\n}", "h": "Cuenta hacia atrás de 3 a 1.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El bucle que repite mientras una condición sea verdadera es ___. (5 letras)", "e": "Olvidar modificar la variable de la condición y crear un bucle infinito."},
  {"m": "Bucles, funciones y arrays", "t": "Bucle do while", "x": "Bucle que ejecuta el bloque al menos una vez y luego comprueba la condición.\n\nLa condición se evalúa al final, por eso el cuerpo se ejecuta como mínimo una vez. Termina con punto y coma después del while.", "u": "Repetir algo que debe hacerse siempre una primera vez.\n\nUn menú debe mostrarse siempre una vez y repetirse solo si el usuario lo pide.", "p": ["do while ejecuta el bloque al menos una vez.", "La condición se evalúa al final.", "do while termina con punto y coma."], "c": "#include <stdio.h>\n\nint main(void) {\n    int i = 10;\n    do {\n        printf(\"i = %d\\n\", i);   // se ejecuta aunque i ya sea grande\n        i++;\n    } while (i < 5);            // punto y coma obligatorio\n    return 0;\n}", "h": "Muestra i una vez aunque la condición sea falsa.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El bucle que se ejecuta al menos una vez es do ___. (5 letras)", "e": "Olvidar el punto y coma después del while."},
  {"m": "Bucles, funciones y arrays", "t": "Bucle for", "x": "Bucle que repite con inicio, condición y paso en una sola línea.\n\nfor (inicio; condición; paso) agrupa lo necesario para controlar el contador. Es el bucle más usado para recorrer rangos y arrays.", "u": "Repetir un número conocido de veces.\n\nQuieres mostrar los números del 1 al 5.", "p": ["for tiene inicio, condición y paso.", "for se usa cuando se conoce el número de repeticiones.", "El contador suele declararse dentro del for."], "c": "#include <stdio.h>\n\nint main(void) {\n    for (int i = 1; i <= 5; i++) {   // inicio; condición; paso\n        printf(\"%d \", i);\n    }\n    printf(\"\\n\");\n    return 0;\n}", "h": "Muestra los números del 1 al 5.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El bucle con inicio, condición y paso es ___. (3 letras)", "e": "Usar <= cuando se quería < y recorrer una vuelta de más."},
  {"m": "Bucles, funciones y arrays", "t": "break", "x": "Instrucción que sale inmediatamente del bucle.\n\nbreak termina el bucle más interno en el que está. También se usa para cerrar los casos de un switch.", "u": "Detener un bucle cuando ya encontraste lo que buscabas.\n\nBuscas un valor en una lista y quieres dejar de recorrer en cuanto lo encuentres.", "p": ["break sale del bucle inmediatamente.", "break afecta al bucle más interno.", "break también cierra los casos de un switch."], "c": "#include <stdio.h>\n\nint main(void) {\n    for (int i = 1; i <= 10; i++) {\n        if (i == 4) break;   // sale del bucle\n        printf(\"%d \", i);\n    }\n    printf(\"\\n\");\n    return 0;\n}", "h": "Muestra números hasta llegar a 4 y sale.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La instrucción que sale de un bucle es ___. (5 letras)", "e": "Creer que break solo sale de la vuelta actual."},
  {"m": "Bucles, funciones y arrays", "t": "continue", "x": "Instrucción que salta a la siguiente vuelta del bucle.\n\ncontinue ignora el resto del cuerpo en esa vuelta y pasa a la siguiente. En un for, antes ejecuta el paso del contador.", "u": "Omitir ciertas vueltas sin terminar el bucle.\n\nQuieres mostrar del 1 al 5 pero sin el número 3.", "p": ["continue salta a la siguiente vuelta.", "continue no termina el bucle.", "Ignora lo que queda del cuerpo en esa vuelta."], "c": "#include <stdio.h>\n\nint main(void) {\n    for (int i = 1; i <= 5; i++) {\n        if (i == 3) continue;   // salta solo esta vuelta\n        printf(\"%d \", i);\n    }\n    printf(\"\\n\");\n    return 0;\n}", "h": "Muestra del 1 al 5 sin el 3.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La instrucción que salta a la siguiente vuelta es ___. (8 letras)", "e": "Confundir continue con break."},
  {"m": "Bucles, funciones y arrays", "t": "Funciones", "x": "Bloque de código con nombre que realiza una tarea y puede reutilizarse.\n\nUna función tiene tipo de retorno, nombre, parámetros y cuerpo. Se llama escribiendo su nombre con paréntesis. Dividir un programa en funciones lo hace más fácil de leer.", "u": "No repetir código y organizar el programa.\n\nRepites el mismo cálculo en cinco lugares del programa.", "p": ["Una función agrupa código reutilizable.", "Una función se llama por su nombre.", "Las funciones organizan el programa."], "c": "#include <stdio.h>\n\nvoid saludar(void) {          // función sin parámetros ni retorno\n    printf(\"Hola desde una función\\n\");\n}\n\nint main(void) {\n    saludar();                // llamada\n    saludar();\n    return 0;\n}", "h": "Llama dos veces a una función que saluda.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una función se ejecuta escribiendo su nombre y ___. (paréntesis)", "e": "Definir una función pero no llamarla."},
  {"m": "Bucles, funciones y arrays", "t": "Parámetros", "x": "Valores que una función recibe para trabajar.\n\nCada parámetro se declara con su tipo entre los paréntesis. Al llamar, se pasan los argumentos en el mismo orden. En C los valores se copian a la función.", "u": "Hacer funciones que sirvan con distintos datos.\n\nQuieres que una función salude al nombre que le indiques.", "p": ["Los parámetros se declaran con su tipo.", "Los argumentos se pasan en el mismo orden.", "En C los valores se pasan por copia."], "c": "#include <stdio.h>\n\nvoid saludar(const char *nombre, int veces) {   // dos parámetros\n    for (int i = 0; i < veces; i++) printf(\"Hola %s\\n\", nombre);\n}\n\nint main(void) {\n    saludar(\"Ana\", 2);\n    return 0;\n}", "h": "Saluda a Ana dos veces usando parámetros.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Los valores que recibe una función se llaman ___. (parámetros)", "e": "Pasar los argumentos en distinto orden que los parámetros."},
  {"m": "Bucles, funciones y arrays", "t": "return", "x": "Instrucción que devuelve un valor y termina la función.\n\nEl valor devuelto debe coincidir con el tipo de retorno de la función. Al ejecutar return, la función termina en ese punto.", "u": "Obtener un resultado de una función.\n\nUna función calcula la suma y quieres usar el resultado en otro lugar.", "p": ["return devuelve un valor desde una función.", "return termina la función.", "El valor debe coincidir con el tipo de retorno."], "c": "#include <stdio.h>\n\nint sumar(int a, int b) {\n    return a + b;               // devuelve el resultado\n}\n\nint main(void) {\n    int total = sumar(2, 3);    // guarda el valor devuelto\n    printf(\"%d\\n\", total);\n    return 0;\n}", "h": "Suma dos números con una función que devuelve el resultado.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La instrucción que devuelve un valor es ___. (6 letras)", "e": "Escribir código después de un return esperando que se ejecute. Después de return la función termina: esa línea nunca se ejecuta."},
  {"m": "Bucles, funciones y arrays", "t": "void", "x": "Tipo que indica ausencia de valor.\n\nUna función void no devuelve resultado. También se escribe en la lista de parámetros, f(void), para indicar que no recibe ninguno.", "u": "Declarar funciones que no devuelven nada.\n\nTu función solo imprime un mensaje y no tiene nada que devolver.", "p": ["void indica que no se devuelve un valor.", "Una función void no usa return con valor.", "f(void) indica que no tiene parámetros."], "c": "#include <stdio.h>\n\nvoid aviso(void) {     // no recibe ni devuelve nada\n    printf(\"Aviso\\n\");\n}\n\nint main(void) {\n    aviso();\n    return 0;\n}", "h": "Llama a una función que no devuelve nada.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo de una función que no devuelve nada es ___. (4 letras)", "e": "Usar el resultado de una función void."},
  {"m": "Bucles, funciones y arrays", "t": "Prototipos", "x": "Declaración de una función antes de su definición.\n\nUn prototipo indica tipo de retorno, nombre y parámetros terminando en punto y coma. Permite llamar a la función aunque su definición esté más abajo.", "u": "Usar una función antes de escribir su cuerpo.\n\nQuieres escribir main arriba y las funciones debajo, sin que el compilador proteste.", "p": ["Un prototipo declara una función sin su cuerpo.", "Termina en punto y coma.", "Permite llamar a la función antes de definirla."], "c": "#include <stdio.h>\n\nint triple(int n);          // prototipo\n\nint main(void) {\n    printf(\"%d\\n\", triple(4));\n    return 0;\n}\n\nint triple(int n) {         // definición\n    return n * 3;\n}", "h": "Declara una función con prototipo y la define después.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La declaración de una función sin cuerpo es un ___. (prototipo)", "e": "Llamar a una función antes de declararla."},
  {"m": "Bucles, funciones y arrays", "t": "Ámbito de variables", "x": "Zona del programa donde una variable es visible.\n\nUna variable local solo existe dentro de las llaves donde se declara. Una global se declara fuera de las funciones y la ven todas, pero conviene evitarlas.", "u": "Evitar conflictos entre variables con el mismo nombre.\n\nDos funciones usan una variable llamada i y no quieres que se pisen.", "p": ["Una variable local solo existe en su bloque.", "Una variable global es visible en todo el archivo.", "Conviene evitar variables globales."], "c": "#include <stdio.h>\n\nint global = 100;           // visible en todo el archivo\n\nint main(void) {\n    int local = 5;          // solo existe dentro de main\n    printf(\"%d %d\\n\", global, local);\n    return 0;\n}", "h": "Muestra una variable global y una local.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una variable declarada dentro de una función es ___. (local)", "e": "Usar una variable local fuera del bloque donde se declaró."},
  {"m": "Bucles, funciones y arrays", "t": "Recursión", "x": "Técnica en la que una función se llama a sí misma.\n\nUna función recursiva necesita un caso base que detenga las llamadas y un caso recursivo que se acerque a él. Sin caso base, el programa agota la memoria de pila.", "u": "Resolver problemas que se repiten en versión más pequeña.\n\nQuieres calcular el factorial de un número definiéndolo en función del factorial del anterior.", "p": ["En la recursión una función se llama a sí misma.", "Necesita un caso base para detenerse.", "Sin caso base se desborda la pila."], "c": "#include <stdio.h>\n\nint factorial(int n) {\n    if (n <= 1) return 1;          // caso base\n    return n * factorial(n - 1);   // caso recursivo\n}\n\nint main(void) {\n    printf(\"%d\\n\", factorial(5));\n    return 0;\n}", "h": "Calcula el factorial de 5 con recursión.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Toda función recursiva necesita un caso ___. (4 letras)", "e": "Olvidar el caso base."},
  {"m": "Bucles, funciones y arrays", "t": "Arrays", "x": "Conjunto de elementos del mismo tipo guardados en posiciones consecutivas.\n\nSe declara con el tipo, el nombre y el tamaño: int notas[5]. Los índices empiezan en 0. C no comprueba que el índice esté dentro del rango.", "u": "Manejar muchos valores con un solo nombre.\n\nDebes guardar cinco notas bajo un solo nombre.", "p": ["Un array guarda varios valores del mismo tipo.", "El primer índice es 0.", "C no comprueba los límites del array."], "c": "#include <stdio.h>\n\nint main(void) {\n    int notas[3] = {7, 9, 8};    // tres elementos\n    printf(\"%d\\n\", notas[0]);   // primer elemento\n    notas[1] = 10;               // modificar uno\n    printf(\"%d\\n\", notas[1]);\n    return 0;\n}", "h": "Guarda tres notas y modifica una.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El primer elemento de un array está en el índice ___. (0)", "e": "Acceder a un índice fuera de los límites del array."},
  {"m": "Bucles, funciones y arrays", "t": "Recorrer arrays", "x": "Visitar cada elemento de un array con un bucle.\n\nSe usa un for con un índice de 0 a n-1. Para saber cuántos elementos tiene, se divide sizeof(array) entre sizeof(array[0]).", "u": "Calcular totales, buscar y mostrar datos.\n\nQuieres sumar todas las notas guardadas en un array.", "p": ["Se recorre un array con un bucle for.", "El índice va de 0 a n-1.", "sizeof permite calcular el número de elementos."], "c": "#include <stdio.h>\n\nint main(void) {\n    int notas[] = {7, 9, 8};\n    int n = sizeof(notas) / sizeof(notas[0]);   // 3 elementos\n    int suma = 0;\n    for (int i = 0; i < n; i++) suma += notas[i];\n    printf(\"%d\\n\", suma);\n    return 0;\n}", "h": "Suma todos los elementos de un array.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un array de n elementos se recorre con índices de 0 a ___. (n-1)", "e": "Recorrer hasta n en lugar de n-1. Con i <= 3 se lee a[3], que no existe: los índices llegan hasta 2."},
  {"m": "Bucles, funciones y arrays", "t": "Cadenas de texto", "x": "Arrays de char que terminan con el carácter nulo.\n\nUna cadena es un array de char terminado en '\\0'. Se escribe entre comillas dobles y el compilador añade el terminador. Se muestra con %s.", "u": "Guardar y manejar texto.\n\nDebes guardar un nombre completo en una variable.", "p": ["Una cadena es un array de char.", "Termina con el carácter nulo.", "Se muestra con %s."], "c": "#include <stdio.h>\n\nint main(void) {\n    char nombre[] = \"Ana\";           // 3 letras + el terminador \\0\n    printf(\"%s\\n\", nombre);\n    printf(\"%c\\n\", nombre[0]);      // primera letra\n    return 0;\n}", "h": "Guarda un nombre en una cadena y muestra su primera letra.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una cadena de C termina con el carácter ___. (nulo)", "e": "Olvidar que la cadena necesita espacio para el terminador."},
  {"m": "Bucles, funciones y arrays", "t": "strlen", "x": "Función que devuelve la longitud de una cadena.\n\nstrlen cuenta los caracteres hasta el terminador nulo, sin contarlo. Está en string.h. Devuelve un size_t.", "u": "Saber cuántos caracteres tiene un texto.\n\nQuieres saber cuántas letras tiene un nombre.", "p": ["strlen devuelve la longitud de una cadena.", "No cuenta el terminador nulo.", "Está en string.h."], "c": "#include <stdio.h>\n#include <string.h>\n\nint main(void) {\n    char nombre[] = \"Carlos\";\n    printf(\"%zu\\n\", strlen(nombre));   // 6\n    return 0;\n}", "h": "Cuenta las letras de un nombre.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que mide una cadena es ___. (6 letras)", "e": "Creer que strlen cuenta el terminador nulo."},
  {"m": "Bucles, funciones y arrays", "t": "strcpy", "x": "Función que copia una cadena en otra.\n\nstrcpy(destino, origen) copia todos los caracteres y el terminador. El destino debe tener espacio suficiente, o habrá un desbordamiento.", "u": "Duplicar el contenido de un texto.\n\nNecesitas copiar un texto en otra variable.", "p": ["strcpy copia una cadena en otra.", "El destino debe tener espacio suficiente.", "Está en string.h."], "c": "#include <stdio.h>\n#include <string.h>\n\nint main(void) {\n    char copia[20];\n    strcpy(copia, \"Hola\");   // destino, origen\n    printf(\"%s\\n\", copia);\n    return 0;\n}", "h": "Copia un texto en otra variable.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que copia cadenas es ___. (6 letras)", "e": "Copiar a un destino demasiado pequeño."},
  {"m": "Bucles, funciones y arrays", "t": "strcmp", "x": "Función que compara dos cadenas.\n\nstrcmp devuelve 0 si las cadenas son iguales, un número negativo si la primera va antes y positivo si va después. No se comparan cadenas con ==.", "u": "Saber si dos textos son iguales o cuál va antes.\n\nQuieres comprobar si dos textos son idénticos.", "p": ["strcmp compara dos cadenas.", "Devuelve 0 si son iguales.", "No se deben comparar cadenas con ==."], "c": "#include <stdio.h>\n#include <string.h>\n\nint main(void) {\n    if (strcmp(\"abc\", \"abc\") == 0) printf(\"iguales\\n\");   // 0 = iguales\n    else printf(\"distintas\\n\");\n    return 0;\n}", "h": "Comprueba que dos cadenas son iguales.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: strcmp devuelve ___ si las cadenas son iguales. (0)", "e": "Comparar cadenas con ==."},
  {"m": "Bucles, funciones y arrays", "t": "Matrices", "x": "Arrays de dos dimensiones con filas y columnas.\n\nSe declaran con dos tamaños: int m[2][3]. Se accede con m[fila][columna] y se recorren con dos bucles for anidados.", "u": "Guardar tablas de datos.\n\nDebes guardar una tabla de 2 filas y 3 columnas.", "p": ["Una matriz es un array con filas y columnas.", "Se accede con dos índices.", "Se recorre con dos bucles anidados."], "c": "#include <stdio.h>\n\nint main(void) {\n    int m[2][3] = {{1, 2, 3}, {4, 5, 6}};   // 2 filas, 3 columnas\n    printf(\"%d\\n\", m[1][2]);               // fila 1, columna 2\n    return 0;\n}", "h": "Guarda una tabla de 2x3 y muestra un elemento.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una matriz se accede con dos ___. (índices)", "e": "Intercambiar fila y columna al acceder."},
  {"m": "Bucles, funciones y arrays", "t": "sizeof", "x": "Operador que devuelve el tamaño en bytes de un tipo o variable.\n\nsizeof se evalúa al compilar y devuelve un size_t. Con arrays permite calcular el número de elementos dividiendo entre el tamaño de un elemento.", "u": "Conocer cuánta memoria ocupa algo.\n\nQuieres saber cuántos bytes ocupa un entero en tu sistema.", "p": ["sizeof devuelve el tamaño en bytes.", "Se evalúa al compilar.", "Sirve para calcular la longitud de un array."], "c": "#include <stdio.h>\n\nint main(void) {\n    int n = 0;\n    printf(\"%zu\\n\", sizeof(int));   // bytes de un int\n    printf(\"%zu\\n\", sizeof(n));\n    return 0;\n}", "h": "Muestra cuántos bytes ocupa un int.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador que da el tamaño en bytes es ___. (6 letras)", "e": "Creer que sizeof de un puntero da el tamaño del array."},
  {"m": "Punteros y memoria", "t": "Punteros", "x": "Variables que guardan la dirección de memoria de otro valor.\n\nUn puntero se declara con un asterisco: int *p. En lugar de un número, guarda la dirección donde vive otro dato. Son la base de la memoria dinámica y de las estructuras de datos.", "u": "Acceder y modificar datos de forma indirecta.\n\nNecesitas que una función modifique directamente una variable de quien la llama.", "p": ["Un puntero guarda una dirección de memoria.", "Se declara con un asterisco.", "Los punteros permiten acceder a los datos de forma indirecta."], "c": "#include <stdio.h>\n\nint main(void) {\n    int x = 10;\n    int *p = &x;          // p guarda la dirección de x\n    printf(\"%d\\n\", *p);  // 10: valor al que apunta\n    return 0;\n}", "h": "Guarda la dirección de una variable en un puntero.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un puntero guarda una ___ de memoria. (dirección)", "e": "Usar un puntero sin inicializarlo."},
  {"m": "Punteros y memoria", "t": "Operador &", "x": "Operador que obtiene la dirección de memoria de una variable.\n\n&x devuelve la dirección donde está x. Se usa para llenar punteros y para pasar variables a funciones como scanf, que escriben en ellas.", "u": "Conseguir el puntero a una variable.\n\nQuieres obtener la dirección de memoria de una variable para guardarla en un puntero.", "p": ["& obtiene la dirección de una variable.", "El resultado de & es un puntero.", "scanf necesita la dirección de la variable."], "c": "#include <stdio.h>\n\nint main(void) {\n    int edad = 30;\n    int *p = &edad;               // & da la dirección\n    printf(\"%d\\n\", p == &edad);  // 1: misma dirección\n    return 0;\n}", "h": "Comprueba que un puntero guarda la dirección de una variable.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador que da la dirección de una variable es ___. (&)", "e": "Olvidar & al pasar una variable a scanf."},
  {"m": "Punteros y memoria", "t": "Desreferenciar con *", "x": "Usar el asterisco para acceder al valor al que apunta un puntero.\n\n*p significa «el valor en la dirección p». Se puede leer y también asignar: *p = 5 cambia la variable original.", "u": "Leer o cambiar el dato apuntado.\n\nTienes un puntero y quieres cambiar el valor de la variable a la que apunta.", "p": ["*p accede al valor al que apunta p.", "*p = valor modifica la variable original.", "Desreferenciar un puntero nulo es un error."], "c": "#include <stdio.h>\n\nint main(void) {\n    int x = 1;\n    int *p = &x;\n    *p = 99;              // cambia x a través del puntero\n    printf(\"%d\\n\", x);\n    return 0;\n}", "h": "Cambia una variable a través de un puntero.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para acceder al valor apuntado se usa el operador ___. (*)", "e": "Desreferenciar un puntero sin inicializar. p no apunta a ninguna parte: escribir en *p es un comportamiento indefinido."},
  {"m": "Punteros y memoria", "t": "Punteros y arrays", "x": "Relación por la cual el nombre de un array actúa como puntero a su primer elemento.\n\nEl nombre de un array equivale a la dirección de su primer elemento. Por eso a[i] y *(a + i) son lo mismo.", "u": "Recorrer y pasar arrays de forma eficiente.\n\nUna función debe recibir un array y recorrerlo.", "p": ["El nombre de un array es la dirección de su primer elemento.", "a[i] equivale a *(a + i).", "Al pasar un array a una función se pasa un puntero."], "c": "#include <stdio.h>\n\nint main(void) {\n    int a[3] = {10, 20, 30};\n    int *p = a;                      // a es la dirección del primer elemento\n    printf(\"%d %d\\n\", p[1], *(a + 2));\n    return 0;\n}", "h": "Accede a elementos de un array usando un puntero.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: a[i] equivale a *(a + ___). (i)", "e": "Creer que sizeof de un array pasado a una función devuelve su tamaño."},
  {"m": "Punteros y memoria", "t": "Aritmética de punteros", "x": "Operaciones de suma y resta sobre direcciones, medidas en elementos.\n\nSi p apunta a un int, p + 1 apunta al siguiente int (avanza sizeof(int) bytes). Así se recorre un array sin usar índices.", "u": "Moverse por un array con un puntero.\n\nQuieres moverte por un array avanzando un puntero elemento a elemento.", "p": ["p + 1 apunta al siguiente elemento.", "La suma avanza según el tamaño del tipo.", "Permite recorrer un array con un puntero."], "c": "#include <stdio.h>\n\nint main(void) {\n    int a[3] = {1, 2, 3};\n    int *p = a;\n    for (int i = 0; i < 3; i++) {\n        printf(\"%d \", *p);\n        p++;                 // pasa al siguiente int\n    }\n    printf(\"\\n\");\n    return 0;\n}", "h": "Recorre un array avanzando un puntero.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Al hacer p++ en un int*, el puntero avanza al siguiente ___. (elemento)", "e": "Avanzar un puntero más allá del final del array."},
  {"m": "Punteros y memoria", "t": "Paso por referencia", "x": "Enviar a una función la dirección de una variable para que la modifique.\n\nC pasa los valores por copia. Para que una función modifique el original se le pasa un puntero. Dentro se usa * para escribir en la variable original.", "u": "Permitir que una función cambie variables del que la llama.\n\nQuieres escribir una función que intercambie los valores de dos variables.", "p": ["Por defecto C pasa los valores por copia.", "Un puntero permite que la función modifique el original.", "Se pasa la dirección con &."], "c": "#include <stdio.h>\n\nvoid duplicar(int *n) {\n    *n = *n * 2;          // modifica el original\n}\n\nint main(void) {\n    int x = 4;\n    duplicar(&x);         // pasa la dirección\n    printf(\"%d\\n\", x);\n    return 0;\n}", "h": "Duplica una variable desde una función usando un puntero.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para que una función modifique el original se le pasa un ___. (puntero)", "e": "Esperar que una función modifique el original cuando se pasó por valor."},
  {"m": "Punteros y memoria", "t": "NULL", "x": "Valor especial de puntero que no apunta a ninguna parte.\n\nConviene inicializar los punteros sin dirección a NULL y comprobarlo antes de usarlos. Funciones como malloc devuelven NULL cuando fallan.", "u": "Indicar que un puntero está vacío o que algo falló.\n\nUn puntero todavía no tiene un dato asignado y quieres marcarlo como vacío.", "p": ["NULL es un puntero que no apunta a nada.", "Conviene comprobar si un puntero es NULL antes de usarlo.", "malloc devuelve NULL si falla."], "c": "#include <stdio.h>\n\nint main(void) {\n    int *p = NULL;               // no apunta a nada\n    if (p == NULL) printf(\"p está vacío\\n\");\n    return 0;\n}", "h": "Comprueba que un puntero está vacío.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El valor de un puntero vacío es ___. (4 letras)", "e": "Desreferenciar un puntero NULL."},
  {"m": "Punteros y memoria", "t": "malloc", "x": "Función que reserva memoria dinámica en el montón.\n\nmalloc(bytes) devuelve un puntero a la memoria reservada, o NULL si no hay. La memoria no se inicializa. Se suele pedir con n * sizeof(tipo).", "u": "Pedir memoria en tiempo de ejecución.\n\nNo sabes cuántos elementos necesitarás hasta ejecutar el programa.", "p": ["malloc reserva memoria dinámica.", "Devuelve NULL si no puede reservar.", "La memoria reservada no está inicializada."], "c": "#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    int *p = malloc(sizeof(int));   // pide memoria para un int\n    if (p == NULL) return 1;\n    *p = 42;\n    printf(\"%d\\n\", *p);\n    free(p);\n    return 0;\n}", "h": "Reserva memoria para un entero, lo usa y la libera.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que reserva memoria dinámica es ___. (6 letras)", "e": "No comprobar si malloc devolvió NULL."},
  {"m": "Punteros y memoria", "t": "free", "x": "Función que libera memoria reservada dinámicamente.\n\nCada malloc debe tener su free. Tras liberar, el puntero queda apuntando a memoria inválida: conviene ponerlo a NULL. Liberar dos veces es un error.", "u": "Devolver al sistema la memoria que ya no usas.\n\nYa no necesitas un bloque de memoria que reservaste.", "p": ["free libera memoria reservada con malloc.", "Cada malloc necesita su free.", "Liberar dos veces la misma memoria es un error."], "c": "#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    int *p = malloc(sizeof(int));\n    *p = 7;\n    free(p);        // libera la memoria\n    p = NULL;       // evita usar un puntero colgante\n    printf(\"liberada\\n\");\n    return 0;\n}", "h": "Libera la memoria y deja el puntero en NULL.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que libera memoria dinámica es ___. (4 letras)", "e": "Usar un puntero después de liberarlo."},
  {"m": "Punteros y memoria", "t": "calloc", "x": "Función que reserva memoria dinámica y la inicializa a cero.\n\ncalloc(n, tamaño) reserva n elementos y pone todos los bytes a cero. Es más seguro que malloc cuando necesitas valores iniciales conocidos.", "u": "Reservar arrays que empiezan con valores en cero.\n\nNecesitas un array dinámico cuyos valores empiecen todos en cero.", "p": ["calloc reserva memoria inicializada a cero.", "Recibe el número de elementos y el tamaño de cada uno.", "También devuelve NULL si falla."], "c": "#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    int *a = calloc(3, sizeof(int));   // 3 enteros en cero\n    printf(\"%d %d %d\\n\", a[0], a[1], a[2]);\n    free(a);\n    return 0;\n}", "h": "Reserva tres enteros inicializados a cero.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que reserva memoria inicializada a cero es ___. (6 letras)", "e": "Creer que malloc inicializa la memoria a cero."},
  {"m": "Punteros y memoria", "t": "realloc", "x": "Función que cambia el tamaño de un bloque de memoria ya reservado.\n\nrealloc(p, nuevo_tamaño) devuelve un puntero al bloque redimensionado, que puede estar en otra dirección. Se guarda en una variable temporal por si devuelve NULL.", "u": "Hacer crecer o encoger un array dinámico.\n\nTu array dinámico se llenó y necesitas más espacio sin perder los datos.", "p": ["realloc cambia el tamaño de un bloque reservado.", "Puede devolver una dirección distinta.", "Conviene guardar el resultado en una variable temporal."], "c": "#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    int *a = malloc(2 * sizeof(int));\n    a[0] = 1; a[1] = 2;\n    int *b = realloc(a, 4 * sizeof(int));   // ahora cabe el doble\n    if (b == NULL) { free(a); return 1; }\n    b[2] = 3; b[3] = 4;\n    printf(\"%d %d\\n\", b[1], b[3]);\n    free(b);\n    return 0;\n}", "h": "Amplía un array dinámico de 2 a 4 enteros.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que redimensiona un bloque es ___. (7 letras)", "e": "Perder el bloque original si realloc falla."},
  {"m": "Punteros y memoria", "t": "Fuga de memoria", "x": "Memoria reservada que nunca se libera.\n\nOcurre cuando pierdes el puntero a un bloque sin llamar a free. Un programa de corta vida lo oculta, pero uno que corre días puede agotar la memoria.", "u": "Entender por qué los programas largos consumen cada vez más memoria.\n\nTu programa consume cada vez más memoria mientras funciona.", "p": ["Una fuga es memoria reservada y no liberada.", "Ocurre al perder el puntero sin hacer free.", "Afecta sobre todo a programas que corren mucho tiempo."], "c": "#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    for (int i = 0; i < 3; i++) {\n        int *p = malloc(100);   // reservamos\n        free(p);                // y liberamos siempre: sin fuga\n    }\n    printf(\"sin fugas\\n\");\n    return 0;\n}", "h": "Reserva y libera memoria en cada vuelta para evitar fugas.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Memoria reservada que no se libera es una ___ de memoria. (fuga)", "e": "Reasignar el puntero sin liberar antes el bloque anterior."},
  {"m": "Punteros y memoria", "t": "Arrays dinámicos", "x": "Arrays cuyo tamaño se decide al ejecutar el programa.\n\nSe piden con malloc(n * sizeof(tipo)) y se usan igual que un array normal. Al terminar se liberan con free.", "u": "Guardar una cantidad de datos desconocida de antemano.\n\nEl usuario elegirá cuántos números guardar y no lo sabes al compilar.", "p": ["Un array dinámico se reserva con malloc.", "Se usa igual que un array normal.", "Debe liberarse con free."], "c": "#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    int n = 4;\n    int *a = malloc(n * sizeof(int));   // tamaño decidido al ejecutar\n    for (int i = 0; i < n; i++) a[i] = i * i;\n    printf(\"%d\\n\", a[3]);\n    free(a);\n    return 0;\n}", "h": "Crea un array dinámico de cuatro cuadrados.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un array dinámico se reserva con ___. (malloc)", "e": "Reservar n bytes en lugar de n * sizeof(tipo)."},
  {"m": "Punteros y memoria", "t": "Puntero a puntero", "x": "Puntero que guarda la dirección de otro puntero.\n\nSe declara con dos asteriscos: int **pp. Permite que una función cambie hacia dónde apunta un puntero del que la llama.", "u": "Modificar un puntero desde una función o manejar arrays de cadenas.\n\nQuieres que una función reserve memoria y deje el puntero del que llama apuntando a ella.", "p": ["Un puntero a puntero se declara con dos asteriscos.", "Guarda la dirección de otro puntero.", "Permite a una función cambiar a dónde apunta un puntero."], "c": "#include <stdio.h>\n\nint main(void) {\n    int x = 8;\n    int *p = &x;\n    int **pp = &p;           // dirección de un puntero\n    printf(\"%d\\n\", **pp);   // 8\n    return 0;\n}", "h": "Accede a una variable a través de un puntero a puntero.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un puntero a puntero se declara con ___ asteriscos. (2)", "e": "Confundir cuántos niveles de * hay que desreferenciar."},
  {"m": "Punteros y memoria", "t": "const con punteros", "x": "Uso de const para proteger el dato apuntado o el puntero.\n\nconst int *p impide modificar el valor apuntado. int * const p impide cambiar a dónde apunta p. Es habitual en parámetros para indicar que la función no modificará el dato.", "u": "Evitar modificaciones accidentales.\n\nUna función solo debe leer un texto y nunca modificarlo.", "p": ["const int *p protege el dato apuntado.", "int * const p protege la dirección guardada.", "Es habitual usarlo en parámetros de solo lectura."], "c": "#include <stdio.h>\n\nvoid mostrar(const char *s) {   // la función no puede modificar s\n    printf(\"%s\\n\", s);\n}\n\nint main(void) {\n    mostrar(\"solo lectura\");\n    return 0;\n}", "h": "Muestra un texto recibido como puntero de solo lectura.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un puntero a un dato de solo lectura se declara const ___ *p. (int)", "e": "Intentar modificar el dato apuntado por un const."},
  {"m": "Punteros y memoria", "t": "Punteros a funciones", "x": "Punteros que guardan la dirección de una función.\n\nSe declaran como tipo (*nombre)(parámetros). Permiten pasar funciones como argumento, lo que se llama callback.", "u": "Elegir qué función ejecutar en tiempo de ejecución.\n\nQuieres pasar a otra función cuál operación debe ejecutar.", "p": ["Un puntero a función guarda la dirección de una función.", "Permite elegir la función a ejecutar.", "Se usa para callbacks."], "c": "#include <stdio.h>\n\nint doble(int n) { return n * 2; }\n\nint main(void) {\n    int (*f)(int) = doble;     // puntero a función\n    printf(\"%d\\n\", f(21));\n    return 0;\n}", "h": "Llama a una función a través de un puntero.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Pasar una función como argumento se llama ___. (callback)", "e": "Olvidar los paréntesis alrededor de (*f) al declararlo."},
  {"m": "Punteros y memoria", "t": "void*", "x": "Puntero genérico que puede apuntar a cualquier tipo.\n\nUn void* no sabe qué tipo apunta, así que antes de usarlo hay que convertirlo al tipo correcto. malloc devuelve void*.", "u": "Escribir funciones que sirvan para varios tipos.\n\nUna función debe aceptar un puntero a cualquier tipo de dato.", "p": ["void* es un puntero genérico.", "Hay que convertirlo antes de desreferenciarlo.", "malloc devuelve un void*."], "c": "#include <stdio.h>\n\nint main(void) {\n    int x = 5;\n    void *p = &x;                 // apunta a cualquier cosa\n    printf(\"%d\\n\", *(int *)p);   // se convierte a int* para usarlo\n    return 0;\n}", "h": "Usa un puntero genérico convirtiéndolo a int*.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El puntero genérico se escribe ___*. (void)", "e": "Desreferenciar un void* sin convertirlo."},
  {"m": "Punteros y memoria", "t": "Cadenas con punteros", "x": "Uso de char* para recorrer y manejar texto.\n\nUn char* puede apuntar al primer carácter de una cadena y avanzar hasta encontrar '\\0'. Un literal como \"hola\" no debe modificarse.", "u": "Manipular cadenas sin índices.\n\nQuieres recorrer un texto carácter por carácter usando un puntero.", "p": ["Un char* apunta al primer carácter de una cadena.", "Se avanza hasta encontrar el terminador nulo.", "Un literal de cadena no debe modificarse."], "c": "#include <stdio.h>\n\nint main(void) {\n    const char *s = \"hola\";\n    int n = 0;\n    while (*s != '\\0') { n++; s++; }   // avanza hasta el terminador\n    printf(\"%d\\n\", n);\n    return 0;\n}", "h": "Cuenta los caracteres de una cadena con un puntero.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una cadena termina con el carácter ___. ('\\0' nulo)", "e": "Modificar un literal de cadena."},
  {"m": "Punteros y memoria", "t": "Pila y montón", "x": "Las dos zonas de memoria: automática (pila) y dinámica (montón).\n\nLas variables locales viven en la pila y desaparecen al salir de la función. La memoria de malloc vive en el montón hasta que la liberas. Devolver la dirección de una local es un error.", "u": "Entender dónde viven las variables.\n\nUna función devuelve la dirección de una variable local y el programa falla después.", "p": ["Las variables locales viven en la pila.", "La memoria de malloc vive en el montón.", "Devolver la dirección de una variable local es un error."], "c": "#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    int local = 1;               // pila\n    int *dinamico = malloc(4);   // montón\n    *dinamico = 2;\n    printf(\"%d %d\\n\", local, *dinamico);\n    free(dinamico);\n    return 0;\n}", "h": "Usa una variable de la pila y otra del montón.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La memoria de malloc vive en el ___. (montón)", "e": "Devolver un puntero a una variable local."},
  {"m": "Punteros y memoria", "t": "Desbordamiento de búfer", "x": "Escribir más datos de los que caben en un array.\n\nOcurre al escribir fuera de los límites de un array. Puede corromper otras variables o permitir ataques. Se evita comprobando tamaños y usando funciones seguras como snprintf.", "u": "Entender uno de los errores de seguridad más graves.\n\nCopias el nombre de un usuario en un array pequeño sin comprobar su longitud.", "p": ["Un desbordamiento escribe fuera de los límites del array.", "Puede corromper datos o permitir ataques.", "Se evita comprobando tamaños."], "c": "#include <stdio.h>\n#include <string.h>\n\nint main(void) {\n    char buf[8];\n    snprintf(buf, sizeof(buf), \"%s\", \"Texto largo que no cabe\");   // limita a 7 + \\0\n    printf(\"%s\\n\", buf);\n    return 0;\n}", "h": "Copia un texto largo en un búfer pequeño sin desbordarlo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Escribir fuera de un array es un ___ de búfer. (desbordamiento)", "e": "Usar funciones que no comprueban el tamaño del destino."},
  {"m": "Estructuras, bits y archivos", "t": "struct", "x": "Tipo compuesto que agrupa varios datos bajo un solo nombre.\n\nUn struct agrupa campos de tipos distintos. Primero se define su forma y luego se declaran variables de ese tipo.", "u": "Representar entidades como una persona o un producto.\n\nQuieres guardar nombre y edad de una persona como una sola unidad.", "p": ["Un struct agrupa varios datos en un solo tipo.", "Cada dato de un struct se llama campo.", "Los campos pueden ser de tipos distintos."], "c": "#include <stdio.h>\n\nstruct Persona {\n    char nombre[20];\n    int edad;\n};\n\nint main(void) {\n    struct Persona p = {\"Ana\", 20};\n    printf(\"%s %d\\n\", p.nombre, p.edad);\n    return 0;\n}", "h": "Define una persona con nombre y edad y la muestra.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra para agrupar datos en un tipo propio es ___. (6 letras)", "e": "Olvidar la palabra struct al declarar la variable."},
  {"m": "Estructuras, bits y archivos", "t": "Acceso a campos", "x": "Uso del punto para leer o cambiar un campo de un struct.\n\nCon variable.campo se lee o se asigna. Las cadenas dentro de un struct se copian con strcpy, no con =.", "u": "Trabajar con cada dato de una estructura.\n\nQuieres cambiar solo la edad de una persona ya creada.", "p": ["El punto accede a un campo de un struct.", "Se puede leer y modificar un campo.", "Las cadenas se copian con strcpy."], "c": "#include <stdio.h>\n\nstruct Punto { int x; int y; };\n\nint main(void) {\n    struct Punto p = {1, 2};\n    p.x = 10;                    // cambia un campo\n    printf(\"%d %d\\n\", p.x, p.y);\n    return 0;\n}", "h": "Modifica un campo de un punto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Se accede a un campo de un struct con un ___. (punto)", "e": "Copiar una cadena de un struct con =."},
  {"m": "Estructuras, bits y archivos", "t": "Puntero a struct", "x": "Puntero que apunta a una estructura y accede a sus campos con ->.\n\nCon un puntero a struct se usa la flecha: p->campo, equivalente a (*p).campo. Evita copiar estructuras grandes al llamar a una función.", "u": "Pasar estructuras a funciones sin copiarlas.\n\nUna función debe modificar una estructura del que la llama sin copiarla.", "p": ["-> accede a un campo a través de un puntero.", "p->campo equivale a (*p).campo.", "Evita copiar estructuras grandes."], "c": "#include <stdio.h>\n\nstruct Punto { int x; int y; };\n\nvoid mover(struct Punto *p) {\n    p->x += 5;                    // flecha: acceso por puntero\n}\n\nint main(void) {\n    struct Punto a = {1, 1};\n    mover(&a);\n    printf(\"%d\\n\", a.x);\n    return 0;\n}", "h": "Mueve un punto a través de un puntero.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para acceder a un campo mediante un puntero se usa la flecha ___. (->)", "e": "Usar el punto en lugar de -> con un puntero. Con un puntero se usa p->x, no p.x."},
  {"m": "Estructuras, bits y archivos", "t": "typedef", "x": "Palabra que crea un nombre nuevo para un tipo.\n\ntypedef struct { ... } Nombre; permite declarar variables sin escribir struct cada vez. También sirve para dar nombres claros a tipos básicos.", "u": "Escribir menos al usar estructuras y tipos largos.\n\nEstás cansado de escribir struct Persona cada vez que declaras una variable.", "p": ["typedef crea un alias para un tipo.", "Evita escribir struct en cada declaración.", "Mejora la legibilidad del código."], "c": "#include <stdio.h>\n\ntypedef struct {\n    char letra;\n    int valor;\n} Carta;                      // ahora basta escribir Carta\n\nint main(void) {\n    Carta c = {'A', 11};\n    printf(\"%c %d\\n\", c.letra, c.valor);\n    return 0;\n}", "h": "Define un tipo Carta con typedef y lo usa.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que crea un alias de tipo es ___. (7 letras)", "e": "Creer que typedef crea un tipo nuevo distinto."},
  {"m": "Estructuras, bits y archivos", "t": "Array de structs", "x": "Array donde cada elemento es una estructura.\n\nSe declara como struct Alumno lista[3] y se accede con lista[i].campo. Se recorre con un bucle for.", "u": "Manejar listas de registros como alumnos o productos.\n\nNecesitas guardar nombre y nota de tres alumnos.", "p": ["Un array de structs guarda muchos registros.", "Se accede con lista[i].campo.", "Se recorre con un bucle."], "c": "#include <stdio.h>\n\ntypedef struct { char nombre[10]; int nota; } Alumno;\n\nint main(void) {\n    Alumno lista[2] = {{\"Ana\", 9}, {\"Luis\", 7}};\n    for (int i = 0; i < 2; i++) printf(\"%s %d\\n\", lista[i].nombre, lista[i].nota);\n    return 0;\n}", "h": "Muestra los alumnos de un array de estructuras.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un elemento de un array de structs se accede con lista[i].___. (campo)", "e": "Olvidar el índice y escribir lista.campo."},
  {"m": "Estructuras, bits y archivos", "t": "Structs anidados", "x": "Estructuras que contienen otras estructuras como campos.\n\nUn campo puede ser de tipo struct. Se accede encadenando puntos: a.b.c. Es útil para agrupar datos relacionados como dirección dentro de persona.", "u": "Modelar datos con partes que a su vez tienen partes.\n\nCada persona tiene una dirección con calle y número y quieres agruparlo todo.", "p": ["Un struct puede contener otro struct.", "Se accede encadenando puntos.", "Agrupa datos relacionados."], "c": "#include <stdio.h>\n\ntypedef struct { int x, y; } Punto;\ntypedef struct { Punto origen; int radio; } Circulo;\n\nint main(void) {\n    Circulo c = {{1, 2}, 5};\n    printf(\"%d\\n\", c.origen.y);   // puntos encadenados\n    return 0;\n}", "h": "Accede a un campo de un struct dentro de otro.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En structs anidados los campos se encadenan con ___. (puntos)", "e": "Olvidar el nombre del campo intermedio."},
  {"m": "Estructuras, bits y archivos", "t": "union", "x": "Tipo cuyos campos comparten la misma zona de memoria.\n\nUna union ocupa lo que su campo más grande. Solo uno de sus campos es válido a la vez: escribir en uno pisa a los demás.", "u": "Ahorrar memoria cuando solo se usa un campo a la vez.\n\nUn dato puede ser entero o decimal, nunca los dos a la vez, y quieres ahorrar memoria.", "p": ["Una union comparte memoria entre sus campos.", "Solo un campo es válido a la vez.", "Ocupa el tamaño de su campo más grande."], "c": "#include <stdio.h>\n\nunion Dato { int i; float f; };\n\nint main(void) {\n    union Dato d;\n    d.i = 7;                     // solo este campo es válido ahora\n    printf(\"%d\\n\", d.i);\n    return 0;\n}", "h": "Guarda un entero en una union.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo cuyos campos comparten memoria es ___. (5 letras)", "e": "Leer un campo distinto del último que se escribió."},
  {"m": "Estructuras, bits y archivos", "t": "enum", "x": "Tipo con un conjunto de constantes enteras con nombre.\n\nLos valores empiezan en 0 y aumentan de uno en uno, salvo que indiques otros. Hace el código más claro que usar números sueltos.", "u": "Dar nombres legibles a opciones o estados.\n\nTu programa usa los estados 0, 1 y 2 y nadie recuerda qué significan.", "p": ["enum define constantes con nombre.", "Los valores empiezan en 0 por defecto.", "Mejora la claridad frente a números sueltos."], "c": "#include <stdio.h>\n\nenum Estado { PENDIENTE, ACTIVO, CERRADO };   // 0, 1, 2\n\nint main(void) {\n    enum Estado e = ACTIVO;\n    printf(\"%d\\n\", e);\n    return 0;\n}", "h": "Usa un estado nombrado en lugar de un número.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo de constantes con nombre es ___. (4 letras)", "e": "Asumir que el primer valor de un enum es 1."},
  {"m": "Estructuras, bits y archivos", "t": "Operadores de bits", "x": "Operadores &, | y ^ que actúan sobre cada bit de un número.\n\n& deja 1 solo si ambos bits son 1, | si alguno es 1 y ^ si son distintos. Se usan para activar, apagar y comprobar bits individuales.", "u": "Manejar banderas y datos a bajo nivel.\n\nQuieres comprobar si un bit concreto de una bandera está encendido.", "p": ["& combina bit a bit con «y».", "| combina bit a bit con «o».", "^ da 1 cuando los bits son distintos."], "c": "#include <stdio.h>\n\nint main(void) {\n    int a = 6, b = 3;            // 110 y 011 en binario\n    printf(\"%d %d %d\\n\", a & b, a | b, a ^ b);\n    return 0;\n}", "h": "Aplica y, o, xor bit a bit a dos números.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador «y» bit a bit es ___. (&)", "e": "Confundir & con &&."},
  {"m": "Estructuras, bits y archivos", "t": "Desplazamientos", "x": "Operadores << y >> que mueven los bits a izquierda o derecha.\n\nx << n desplaza n posiciones a la izquierda (multiplica por 2^n) y x >> n a la derecha (divide). Se usan para crear máscaras como 1 << 3.", "u": "Multiplicar o dividir por potencias de dos y armar máscaras.\n\nQuieres multiplicar un entero por 8 de forma rápida con bits.", "p": ["<< desplaza los bits a la izquierda.", ">> desplaza los bits a la derecha.", "x << n equivale a multiplicar por 2 elevado a n."], "c": "#include <stdio.h>\n\nint main(void) {\n    int x = 3;\n    printf(\"%d\\n\", x << 3);   // 3 * 8 = 24\n    printf(\"%d\\n\", 16 >> 2);  // 16 / 4 = 4\n    return 0;\n}", "h": "Desplaza bits para multiplicar y dividir.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Desplazar a la izquierda se escribe con ___. (<<)", "e": "Confundir << con el operador de comparación."},
  {"m": "Estructuras, bits y archivos", "t": "fopen y fclose", "x": "Funciones para abrir y cerrar archivos.\n\nfopen(nombre, modo) devuelve un FILE* o NULL si falla. Los modos principales son \"r\" (leer), \"w\" (escribir) y \"a\" (añadir). Al terminar se cierra con fclose.", "u": "Leer y guardar datos en disco.\n\nDebes guardar datos en un archivo y asegurarte de cerrarlo al terminar.", "p": ["fopen abre un archivo.", "fclose lo cierra.", "fopen devuelve NULL si falla."], "c": "#include <stdio.h>\n\nint main(void) {\n    FILE *f = fopen(\"datos.txt\", \"w\");   // \"w\": escribir\n    if (f == NULL) return 1;\n    fputs(\"hola\\n\", f);\n    fclose(f);                           // siempre se cierra\n    printf(\"archivo creado\\n\");\n    return 0;\n}", "h": "Crea un archivo, escribe en él y lo cierra.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que abre un archivo es ___. (5 letras)", "e": "No comprobar si fopen devolvió NULL."},
  {"m": "Estructuras, bits y archivos", "t": "fprintf", "x": "Función que escribe texto con formato en un archivo.\n\nFunciona como printf pero con un primer argumento extra: el archivo donde escribir.", "u": "Guardar datos con formato en un archivo.\n\nQuieres guardar «Ana 9» en un archivo con formato.", "p": ["fprintf escribe texto con formato en un archivo.", "Su primer argumento es el archivo.", "Funciona como printf."], "c": "#include <stdio.h>\n\nint main(void) {\n    FILE *f = fopen(\"notas.txt\", \"w\");\n    fprintf(f, \"%s %d\\n\", \"Ana\", 9);   // como printf pero al archivo\n    fclose(f);\n    printf(\"guardado\\n\");\n    return 0;\n}", "h": "Guarda un nombre y una nota en un archivo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La versión de printf que escribe en un archivo es ___. (7 letras)", "e": "Olvidar el archivo como primer argumento de fprintf."},
  {"m": "Estructuras, bits y archivos", "t": "fgets", "x": "Función que lee una línea de texto de un archivo.\n\nfgets(buffer, tamaño, archivo) lee como máximo tamaño-1 caracteres. Devuelve NULL al llegar al final. Es la alternativa segura a gets, que ya no existe.", "u": "Leer texto línea a línea de forma segura.\n\nQuieres leer un archivo línea a línea sin riesgo de desbordar el búfer.", "p": ["fgets lee una línea de texto.", "Limita la lectura al tamaño del búfer.", "Devuelve NULL al final del archivo."], "c": "#include <stdio.h>\n\nint main(void) {\n    FILE *f = fopen(\"lineas.txt\", \"w\");\n    fputs(\"uno\\ndos\\n\", f);\n    fclose(f);\n    f = fopen(\"lineas.txt\", \"r\");\n    char linea[20];\n    while (fgets(linea, sizeof(linea), f)) printf(\"%s\", linea);\n    fclose(f);\n    return 0;\n}", "h": "Escribe dos líneas en un archivo y las lee con fgets.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función segura para leer una línea es ___. (5 letras)", "e": "Usar gets, que no limita el tamaño."},
  {"m": "Estructuras, bits y archivos", "t": "fscanf", "x": "Función que lee datos con formato desde un archivo.\n\nFunciona como scanf pero sobre un archivo. Devuelve cuántos datos leyó, o EOF al terminar.", "u": "Leer números y palabras sueltas de un archivo.\n\nTienes un archivo con números separados por espacios y quieres leerlos.", "p": ["fscanf lee datos con formato de un archivo.", "Devuelve el número de datos leídos.", "Funciona como scanf."], "c": "#include <stdio.h>\n\nint main(void) {\n    FILE *f = fopen(\"n.txt\", \"w\");\n    fprintf(f, \"10 20\");\n    fclose(f);\n    f = fopen(\"n.txt\", \"r\");\n    int a, b;\n    fscanf(f, \"%d %d\", &a, &b);   // lee dos enteros\n    fclose(f);\n    printf(\"%d\\n\", a + b);\n    return 0;\n}", "h": "Lee dos números de un archivo y los suma.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La versión de scanf para archivos es ___. (6 letras)", "e": "Olvidar & en las variables de fscanf."},
  {"m": "Estructuras, bits y archivos", "t": "fwrite y fread", "x": "Funciones para escribir y leer bloques de bytes.\n\nfwrite(dato, tamaño, cantidad, archivo) guarda bytes tal cual. fread hace lo contrario. El archivo se abre en modo binario (\"wb\" o \"rb\").", "u": "Guardar estructuras completas en formato binario.\n\nQuieres guardar una estructura completa en un archivo de una sola vez.", "p": ["fwrite escribe bloques de bytes.", "fread lee bloques de bytes.", "Se usan con modos binarios wb y rb."], "c": "#include <stdio.h>\n\nint main(void) {\n    int n = 42, leido = 0;\n    FILE *f = fopen(\"bin.dat\", \"wb\");\n    fwrite(&n, sizeof(int), 1, f);     // guarda 4 bytes\n    fclose(f);\n    f = fopen(\"bin.dat\", \"rb\");\n    fread(&leido, sizeof(int), 1, f);  // los recupera\n    fclose(f);\n    printf(\"%d\\n\", leido);\n    return 0;\n}", "h": "Guarda un entero en binario y lo vuelve a leer.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que escribe bloques binarios es ___. (6 letras)", "e": "Abrir en modo texto un archivo binario."},
  {"m": "Estructuras, bits y archivos", "t": "argc y argv", "x": "Parámetros de main que reciben los argumentos de la línea de comandos.\n\nargc es la cantidad de argumentos y argv un array de cadenas. argv[0] es el nombre del programa. Se declara como int main(int argc, char *argv[]).", "u": "Recibir datos al ejecutar el programa.\n\nQuieres que el usuario escriba una opción al ejecutar el programa.", "p": ["argc es el número de argumentos.", "argv es un array de cadenas.", "argv[0] es el nombre del programa."], "c": "#include <stdio.h>\n\nint main(int argc, char *argv[]) {\n    printf(\"argumentos: %d\\n\", argc);    // al menos 1: el programa\n    if (argc > 1) printf(\"primero: %s\\n\", argv[1]);\n    return 0;\n}", "h": "Muestra cuántos argumentos recibió el programa.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El número de argumentos de main se llama ___. (argc)", "e": "Usar argv[1] sin comprobar que existe."},
  {"m": "Estructuras, bits y archivos", "t": "snprintf", "x": "Función que escribe texto con formato en una cadena con límite de tamaño.\n\nsnprintf(destino, tamaño, formato, ...) escribe sin superar el tamaño dado, así evita desbordamientos. Es la alternativa segura a sprintf.", "u": "Construir textos de forma segura.\n\nQuieres construir un mensaje en una cadena sin riesgo de desbordarla.", "p": ["snprintf escribe texto con formato en una cadena.", "Limita la escritura al tamaño indicado.", "Es más segura que sprintf."], "c": "#include <stdio.h>\n\nint main(void) {\n    char msg[30];\n    snprintf(msg, sizeof(msg), \"Hola %s, tienes %d\", \"Ana\", 20);\n    printf(\"%s\\n\", msg);\n    return 0;\n}", "h": "Construye un mensaje en una cadena de forma segura.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La versión segura para escribir en una cadena es ___. (8 letras)", "e": "Usar sprintf sin controlar el tamaño."},
  {"m": "Estructuras, bits y archivos", "t": "sscanf", "x": "Función que lee datos con formato desde una cadena.\n\nFunciona como scanf pero la entrada es una cadena en memoria. Devuelve cuántos valores pudo leer.", "u": "Extraer números o palabras de un texto.\n\nTienes el texto «12 34» y quieres sacar los dos números.", "p": ["sscanf lee datos con formato de una cadena.", "Devuelve cuántos valores leyó.", "Sirve para extraer números de un texto."], "c": "#include <stdio.h>\n\nint main(void) {\n    int a, b;\n    sscanf(\"12 34\", \"%d %d\", &a, &b);   // lee desde una cadena\n    printf(\"%d\\n\", a * b);\n    return 0;\n}", "h": "Extrae dos números de un texto y los multiplica.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que lee datos desde una cadena es ___. (6 letras)", "e": "No comprobar el valor que devuelve sscanf."},
  {"m": "Estructuras, bits y archivos", "t": "rand y srand", "x": "Funciones para generar números pseudoaleatorios.\n\nrand() devuelve un número pseudoaleatorio. Si no se cambia la semilla con srand, cada ejecución da la misma secuencia. Se suele usar srand(time(NULL)).", "u": "Simular azar en juegos y pruebas.\n\nNecesitas simular una tirada de dado.", "p": ["rand genera números pseudoaleatorios.", "srand cambia la semilla.", "Sin cambiar la semilla la secuencia se repite."], "c": "#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    srand(7);                       // semilla fija: resultado repetible\n    int dado = rand() % 6 + 1;      // entre 1 y 6\n    printf(\"%s\\n\", (dado >= 1 && dado <= 6) ? \"válido\" : \"fuera de rango\");\n    return 0;\n}", "h": "Simula un dado y comprueba que está entre 1 y 6.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que genera un número pseudoaleatorio es ___. (4 letras)", "e": "Olvidar cambiar la semilla y obtener siempre lo mismo."},
  {"m": "Estructuras, bits y archivos", "t": "qsort", "x": "Función que ordena un array con una función de comparación.\n\nqsort(array, n, tamaño, comparar) ordena en el lugar. La función de comparación devuelve negativo, cero o positivo según el orden.", "u": "Ordenar datos de cualquier tipo.\n\nQuieres ordenar un array de enteros sin escribir tu propio algoritmo.", "p": ["qsort ordena un array.", "Recibe una función de comparación.", "La comparación devuelve un valor negativo, cero o positivo."], "c": "#include <stdio.h>\n#include <stdlib.h>\n\nint comparar(const void *a, const void *b) {\n    return *(const int *)a - *(const int *)b;   // menor a mayor\n}\n\nint main(void) {\n    int v[4] = {3, 1, 4, 2};\n    qsort(v, 4, sizeof(int), comparar);\n    for (int i = 0; i < 4; i++) printf(\"%d \", v[i]);\n    printf(\"\\n\");\n    return 0;\n}", "h": "Ordena un array de enteros de menor a mayor.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función estándar para ordenar arrays es ___. (5 letras)", "e": "Devolver un valor incorrecto en la función de comparación."},
  {"m": "C profesional", "t": "Archivos de cabecera", "x": "Archivos .h que declaran funciones y tipos para otros archivos.\n\nUn .h contiene prototipos y tipos; el .c contiene la implementación. Quien necesite las funciones incluye el .h con comillas: #include \"mates.h\".", "u": "Dividir un programa en varios archivos.\n\nTu programa creció y quieres separar las funciones de cálculo en otro archivo.", "p": ["Un archivo .h declara funciones y tipos.", "El .c contiene la implementación.", "Las cabeceras propias se incluyen con comillas."], "c": "#include <stdio.h>\n\n/* mates.h:   int doble(int n);        <- declaración\n   mates.c:   int doble(int n) {...}   <- implementación */\nint doble(int n) { return n * 2; }\n\nint main(void) {\n    printf(\"%d\\n\", doble(21));\n    return 0;\n}", "h": "Usa una función que vive en su propio módulo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Las declaraciones se guardan en archivos con extensión ___. (.h)", "e": "Definir funciones en un .h incluido desde varios archivos."},
  {"m": "C profesional", "t": "Include guards", "x": "Directivas que evitan incluir una cabecera más de una vez.\n\nSe escriben con #ifndef, #define y #endif alrededor del contenido del .h. Si el archivo ya se incluyó, el compilador lo ignora.", "u": "Prevenir errores de declaraciones duplicadas.\n\nUna cabecera se incluye dos veces y el compilador protesta por redefiniciones.", "p": ["Los include guards evitan inclusiones duplicadas.", "Usan #ifndef, #define y #endif.", "Se colocan en las cabeceras."], "c": "#include <stdio.h>\n#ifndef MATES_H      // si aún no se definió...\n#define MATES_H      // ...se define y se incluye el contenido\n#define VERSION 1\n#endif               // fin del guarda\n\nint main(void) {\n    printf(\"%d\\n\", VERSION);\n    return 0;\n}", "h": "Protege una definición con include guards.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El guarda empieza con #___ y un nombre. (ifndef)", "e": "Usar el mismo nombre de guarda en dos cabeceras."},
  {"m": "C profesional", "t": "Makefile", "x": "Archivo que automatiza la compilación del proyecto.\n\nUn Makefile describe objetivos, dependencias y comandos. make compara fechas y recompila solo los archivos modificados.", "u": "Compilar solo lo que cambió con un único comando.\n\nTu proyecto tiene muchos archivos y compilar a mano es lento y propenso a errores.", "p": ["Un Makefile automatiza la compilación.", "make recompila solo lo que cambió.", "Describe objetivos, dependencias y comandos."], "c": "#include <stdio.h>\n\n/* Makefile:\n   programa: main.c util.c\n   <tab>gcc -Wall main.c util.c -o programa */\nint main(void) {\n    printf(\"compilado con make\\n\");\n    return 0;\n}", "h": "Muestra un mensaje; el comentario describe un Makefile.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La herramienta que lee un Makefile es ___. (4 letras)", "e": "Usar espacios en lugar de tabulador en los comandos del Makefile."},
  {"m": "C profesional", "t": "static", "x": "Modificador que fija la duración o el alcance de una variable o función.\n\nUna variable local static conserva su valor entre llamadas. Una función o variable global static solo es visible dentro de su archivo.", "u": "Conservar valores entre llamadas o ocultar funciones al resto de archivos.\n\nUna función debe recordar cuántas veces fue llamada.", "p": ["Una variable local static conserva su valor entre llamadas.", "Una función static solo es visible en su archivo.", "static se inicializa una sola vez."], "c": "#include <stdio.h>\n\nint contar(void) {\n    static int n = 0;     // se inicializa una sola vez\n    return ++n;\n}\n\nint main(void) {\n    contar(); contar();\n    printf(\"%d\\n\", contar());\n    return 0;\n}", "h": "Cuenta las llamadas con una variable static.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El modificador que conserva el valor entre llamadas es ___. (6 letras)", "e": "Esperar que una variable local normal conserve su valor."},
  {"m": "C profesional", "t": "extern", "x": "Palabra que declara una variable definida en otro archivo.\n\nextern int n; avisa de que n existe en otro lugar. La definición real, con memoria, está en un solo archivo.", "u": "Compartir una variable global entre archivos.\n\nDos archivos necesitan compartir el mismo contador global.", "p": ["extern declara una variable definida en otro archivo.", "No reserva memoria.", "La definición debe estar en un solo archivo."], "c": "#include <stdio.h>\n\nint total = 5;           // definición (un solo archivo)\nextern int total;        // declaración: otro archivo escribiría solo esto\n\nint main(void) {\n    printf(\"%d\\n\", total);\n    return 0;\n}", "h": "Declara y usa una variable global.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que declara una variable definida en otro archivo es ___. (6 letras)", "e": "Definir la misma variable global en dos archivos."},
  {"m": "C profesional", "t": "Macros con argumentos", "x": "Macros #define que reciben parámetros.\n\nEl preprocesador sustituye el texto. Conviene poner paréntesis alrededor de cada parámetro y de toda la expresión para evitar sorpresas con la precedencia.", "u": "Escribir pequeñas operaciones sin llamar a una función.\n\nQuieres una operación cortísima como calcular el cuadrado sin crear una función.", "p": ["Una macro con argumentos se sustituye como texto.", "Conviene proteger cada parámetro con paréntesis.", "No comprueba tipos."], "c": "#include <stdio.h>\n#define CUADRADO(x) ((x) * (x))   // paréntesis para evitar errores\n\nint main(void) {\n    printf(\"%d\\n\", CUADRADO(2 + 3));   // 25\n    return 0;\n}", "h": "Calcula un cuadrado con una macro.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una macro con parámetros se define con #___. (define)", "e": "Olvidar los paréntesis dentro de la macro."},
  {"m": "C profesional", "t": "Compilación condicional", "x": "Directivas que incluyen o excluyen código según una condición.\n\n#ifdef incluye un bloque solo si existe una macro. Se usa para activar mensajes de depuración con -DDEBUG.", "u": "Adaptar el programa a distintas plataformas o modos.\n\nQuieres mensajes de depuración solo mientras desarrollas.", "p": ["#ifdef incluye código si una macro existe.", "#endif cierra el bloque condicional.", "Sirve para activar o quitar depuración."], "c": "#include <stdio.h>\n#define DEBUG 1\n\nint main(void) {\n#ifdef DEBUG\n    printf(\"modo depuración\\n\");   // solo se compila si DEBUG existe\n#endif\n    printf(\"fin\\n\");\n    return 0;\n}", "h": "Muestra un mensaje solo si DEBUG está definido.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La directiva que incluye código si una macro existe es #___. (ifdef)", "e": "Olvidar el #endif."},
  {"m": "C profesional", "t": "assert", "x": "Macro que comprueba una condición y detiene el programa si es falsa.\n\nassert(condición) está en assert.h. Si la condición es falsa, muestra dónde falló y aborta. Con -DNDEBUG se desactiva.", "u": "Detectar errores de lógica durante el desarrollo.\n\nQuieres asegurarte durante el desarrollo de que un divisor nunca sea cero.", "p": ["assert detiene el programa si la condición es falsa.", "Está en assert.h.", "Se desactiva con NDEBUG."], "c": "#include <stdio.h>\n#include <assert.h>\n\nint dividir(int a, int b) {\n    assert(b != 0);        // si falla, el programa se detiene\n    return a / b;\n}\n\nint main(void) {\n    printf(\"%d\\n\", dividir(10, 2));\n    return 0;\n}", "h": "Comprueba que el divisor no sea cero antes de dividir.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La macro que comprueba condiciones es ___. (6 letras)", "e": "Usar assert para validar entradas del usuario."},
  {"m": "C profesional", "t": "errno y perror", "x": "Mecanismo que informa del motivo de un fallo del sistema.\n\nCuando una función del sistema falla, guarda un código en errno. perror muestra un mensaje legible basado en él.", "u": "Mostrar mensajes claros cuando una función falla.\n\nfopen devolvió NULL y quieres explicar por qué falló.", "p": ["errno guarda el código del último error.", "perror muestra un mensaje descriptivo.", "Se usan cuando una función devuelve un fallo."], "c": "#include <stdio.h>\n#include <errno.h>\n\nint main(void) {\n    FILE *f = fopen(\"no_existe.txt\", \"r\");\n    if (f == NULL) printf(\"error %d\\n\", errno);   // ENOENT = 2\n    return 0;\n}", "h": "Muestra el código de error al abrir un archivo inexistente.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La variable que guarda el código de error es ___. (errno)", "e": "Ignorar el valor de retorno de funciones que pueden fallar."},
  {"m": "C profesional", "t": "Advertencias del compilador", "x": "Avisos de gcc sobre posibles errores con opciones como -Wall.\n\nCompila siempre con -Wall -Wextra. Una advertencia no impide compilar, pero suele señalar un error real, como una variable sin usar o un formato incorrecto.", "u": "Detectar problemas antes de ejecutar.\n\nTu programa compila pero se comporta raro y gcc no dijo nada.", "p": ["-Wall activa las advertencias principales.", "Una advertencia suele señalar un error real.", "Conviene tratar las advertencias como errores."], "c": "#include <stdio.h>\n\nint main(void) {\n    int n = 5;\n    printf(\"%d\\n\", n);   // gcc -Wall -Wextra avisaría de errores de formato\n    return 0;\n}", "h": "Muestra un valor con un formato correcto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La opción que activa las advertencias principales es -W___. (all)", "e": "Ignorar las advertencias del compilador."},
  {"m": "C profesional", "t": "Depuración con gdb", "x": "Uso de un depurador para ejecutar el programa paso a paso.\n\ngdb permite poner puntos de parada, avanzar línea a línea e inspeccionar variables. Compila con -g para incluir la información necesaria.", "u": "Encontrar la causa de un fallo.\n\nTu programa se cae con «segmentation fault» y no sabes dónde.", "p": ["gdb ejecuta el programa paso a paso.", "Permite inspeccionar variables.", "Hay que compilar con -g."], "c": "#include <stdio.h>\n\nint main(void) {\n    int suma = 0;\n    for (int i = 1; i <= 3; i++) suma += i;   // gdb: break main, next, print suma\n    printf(\"%d\\n\", suma);\n    return 0;\n}", "h": "Suma del 1 al 3, ideal para depurar paso a paso.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El depurador de GNU se llama ___. (3 letras)", "e": "Depurar sin compilar con -g."},
  {"m": "C profesional", "t": "Valgrind", "x": "Herramienta que detecta fugas y errores de memoria.\n\nEjecutas tu programa con valgrind ./programa y te informa de lecturas fuera de rango, usos de memoria liberada y bloques no liberados.", "u": "Encontrar accesos inválidos y memoria sin liberar.\n\nSospechas que tu programa tiene una fuga de memoria.", "p": ["Valgrind detecta fugas de memoria.", "Detecta accesos inválidos a memoria.", "Se ejecuta con valgrind ./programa."], "c": "#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    int *p = malloc(sizeof(int));\n    *p = 1;\n    printf(\"%d\\n\", *p);\n    free(p);            // valgrind confirmaría que no hay fugas\n    return 0;\n}", "h": "Reserva y libera memoria, sin fugas.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La herramienta que detecta fugas de memoria es ___. (8 letras)", "e": "Creer que un programa sin fallos visibles no tiene fugas."},
  {"m": "C profesional", "t": "Tipos de ancho fijo", "x": "Tipos de stdint.h con tamaño exacto como int32_t.\n\nint puede tener distinto tamaño según el sistema. Con int32_t, uint8_t o int64_t el tamaño es siempre el mismo.", "u": "Escribir código con tamaños predecibles en cualquier plataforma.\n\nNecesitas un entero de exactamente 32 bits en cualquier computadora.", "p": ["Los tipos de ancho fijo tienen un tamaño exacto.", "Están en stdint.h.", "Dan portabilidad entre plataformas."], "c": "#include <stdio.h>\n#include <stdint.h>\n\nint main(void) {\n    int32_t a = 100000;\n    uint8_t b = 200;           // 0 a 255\n    printf(\"%d %d\\n\", (int)a, (int)b);\n    return 0;\n}", "h": "Usa enteros de tamaño exacto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La cabecera con enteros de ancho fijo es ___.h. (stdint)", "e": "Suponer que int siempre tiene 32 bits."},
  {"m": "C profesional", "t": "size_t", "x": "Tipo entero sin signo para tamaños y conteos.\n\nsizeof y strlen devuelven size_t. Se imprime con %zu. Al ser sin signo, restar de más puede dar un número enorme.", "u": "Representar tamaños de memoria y longitudes.\n\nQuieres guardar el resultado de strlen en una variable del tipo adecuado.", "p": ["size_t guarda tamaños y conteos.", "No tiene signo.", "Se imprime con %zu."], "c": "#include <stdio.h>\n#include <string.h>\n\nint main(void) {\n    size_t n = strlen(\"hola\");\n    printf(\"%zu\\n\", n);\n    return 0;\n}", "h": "Guarda la longitud de una cadena en un size_t.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo de los tamaños es ___. (size_t)", "e": "Restar de un size_t y obtener un número negativo."},
  {"m": "C profesional", "t": "Biblioteca math.h", "x": "Cabecera con funciones matemáticas como sqrt y pow.\n\nIncluye sqrt (raíz), pow (potencia), sin, cos, fabs y más. En muchos sistemas hay que enlazar con -lm al compilar.", "u": "Hacer cálculos matemáticos.\n\nNecesitas calcular la raíz cuadrada y una potencia.", "p": ["math.h ofrece funciones matemáticas.", "sqrt calcula la raíz cuadrada.", "Puede requerir enlazar con -lm."], "c": "#include <stdio.h>\n#include <math.h>\n\nint main(void) {\n    printf(\"%.0f\\n\", sqrt(81.0));    // 9\n    printf(\"%.0f\\n\", pow(2.0, 10.0)); // 1024\n    return 0;\n}", "h": "Calcula una raíz cuadrada y una potencia.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La cabecera de funciones matemáticas es ___.h. (math)", "e": "Olvidar enlazar con -lm."},
  {"m": "C profesional", "t": "Biblioteca ctype.h", "x": "Cabecera con funciones para clasificar y convertir caracteres.\n\nisalpha, isdigit y isspace clasifican; toupper y tolower convierten. Trabajan carácter a carácter.", "u": "Validar letras, dígitos y pasar a mayúsculas.\n\nQuieres comprobar si un carácter es un dígito.", "p": ["ctype.h clasifica caracteres.", "toupper pasa un carácter a mayúscula.", "isdigit comprueba si es un dígito."], "c": "#include <stdio.h>\n#include <ctype.h>\n\nint main(void) {\n    printf(\"%d\\n\", isdigit('7') != 0);    // 1\n    printf(\"%c\\n\", toupper('a'));         // A\n    return 0;\n}", "h": "Comprueba un dígito y pasa una letra a mayúscula.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que pasa un carácter a mayúscula es ___. (toupper)", "e": "Aplicar toupper a una cadena entera sin recorrerla."},
  {"m": "C profesional", "t": "Listas enlazadas", "x": "Estructura de nodos conectados mediante punteros.\n\nCada nodo guarda un dato y un puntero al siguiente. Insertar al inicio es rápido; para llegar a un elemento hay que recorrer desde la cabeza.", "u": "Guardar datos que crecen y cambian con facilidad.\n\nNecesitas insertar elementos con frecuencia sin redimensionar un array.", "p": ["Una lista enlazada se compone de nodos con punteros.", "Cada nodo apunta al siguiente.", "Se accede recorriendo desde la cabeza."], "c": "#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct Nodo { int dato; struct Nodo *sig; } Nodo;\n\nint main(void) {\n    Nodo *b = malloc(sizeof(Nodo)); b->dato = 2; b->sig = NULL;\n    Nodo *a = malloc(sizeof(Nodo)); a->dato = 1; a->sig = b;\n    for (Nodo *p = a; p; p = p->sig) printf(\"%d \", p->dato);\n    printf(\"\\n\");\n    free(a); free(b);\n    return 0;\n}", "h": "Crea una lista de dos nodos y la recorre.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En una lista enlazada cada nodo apunta al ___. (siguiente)", "e": "Perder la cabeza de la lista."},
  {"m": "C profesional", "t": "Pilas y colas", "x": "Estructuras con orden fijo: la pila saca el último, la cola el primero.\n\nUna pila es LIFO: el último en entrar es el primero en salir. Una cola es FIFO: el primero en entrar es el primero en salir.", "u": "Modelar deshacer, turnos y recorridos.\n\nQuieres implementar el botón deshacer, donde se revierte lo último hecho.", "p": ["Una pila es LIFO.", "Una cola es FIFO.", "Ambas controlan el orden de salida."], "c": "#include <stdio.h>\n\nint main(void) {\n    int pila[3], tope = 0;\n    pila[tope++] = 1;          // apilar\n    pila[tope++] = 2;\n    pila[tope++] = 3;\n    printf(\"%d\\n\", pila[--tope]);   // desapilar: sale el último (3)\n    return 0;\n}", "h": "Apila tres valores y desapila el último.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La pila sigue el orden LIFO: el último en ___ es el primero en salir. (entrar)", "e": "Confundir pila (LIFO) con cola (FIFO)."},
  {"m": "C profesional", "t": "Búsqueda binaria", "x": "Algoritmo que busca en una lista ordenada dividiéndola por la mitad.\n\nCompara con el elemento central y descarta la mitad que no puede contenerlo. Necesita que la lista esté ordenada y es mucho más rápida que recorrer todo.", "u": "Encontrar un valor rápidamente en datos ordenados.\n\nTienes un millón de números ordenados y buscas uno con pocas comparaciones.", "p": ["La búsqueda binaria requiere una lista ordenada.", "Descarta la mitad en cada paso.", "Es mucho más rápida que la búsqueda lineal."], "c": "#include <stdio.h>\n\nint buscar(int v[], int n, int x) {\n    int ini = 0, fin = n - 1;\n    while (ini <= fin) {\n        int mid = (ini + fin) / 2;\n        if (v[mid] == x) return mid;\n        if (v[mid] < x) ini = mid + 1; else fin = mid - 1;\n    }\n    return -1;\n}\n\nint main(void) {\n    int v[] = {1, 3, 5, 7, 9};\n    printf(\"%d\\n\", buscar(v, 5, 7));\n    return 0;\n}", "h": "Busca un número en un array ordenado y muestra su posición.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La búsqueda binaria exige que la lista esté ___. (ordenada)", "e": "Aplicar búsqueda binaria a una lista desordenada."},
  {"m": "C profesional", "t": "Ordenamiento burbuja", "x": "Algoritmo que ordena intercambiando elementos vecinos fuera de orden.\n\nRecorre la lista varias veces comparando pares contiguos. En cada pasada el mayor «sube» al final. Es fácil de entender pero lento con muchos datos.", "u": "Aprender cómo funciona un ordenamiento simple.\n\nQuieres entender un algoritmo de ordenamiento sencillo para practicar bucles.", "p": ["El ordenamiento burbuja compara elementos vecinos.", "Intercambia los que están fuera de orden.", "Es lento con muchos datos."], "c": "#include <stdio.h>\n\nint main(void) {\n    int v[4] = {4, 2, 3, 1};\n    for (int i = 0; i < 3; i++)\n        for (int j = 0; j < 3 - i; j++)\n            if (v[j] > v[j + 1]) { int t = v[j]; v[j] = v[j + 1]; v[j + 1] = t; }\n    for (int i = 0; i < 4; i++) printf(\"%d \", v[i]);\n    printf(\"\\n\");\n    return 0;\n}", "h": "Ordena un array pequeño con el método de la burbuja.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El algoritmo que intercambia vecinos fuera de orden es el de la ___. (burbuja)", "e": "Usar burbuja con millones de datos."}
];
